"use strict";

/**
 * Read-only settings observations for a future persistent authority protocol.
 * Only Node builtins: CJS readers must not materialize a require(ESM) bridge.
 *
 * These checks detect ordinary replacement and in-place edits. Path-based Node
 * APIs do not prevent an adversarial parent swap-and-restore between checks.
 * No observation is a generation, registration, or permission grant.
 */
const fsDefault = require("node:fs");
const path = require("node:path");
const { createHash } = require("node:crypto");
const { TextDecoder } = require("node:util");

const MAX_SETTINGS_SOURCE_BYTES = 1024 * 1024;
const MAX_SETTINGS_SOURCES = 64;
const FILE_FIELDS = [
  "dev",
  "ino",
  "mode",
  "nlink",
  "size",
  "mtimeNs",
  "ctimeNs",
];

function failure(code, cause = null) {
  const error = new Error(
    "Settings source observation is unavailable",
    cause ? { cause } : undefined,
  );
  error.name = "SettingsSourceObservationError";
  error.code = code;
  return error;
}

function sameFields(left, right, fields) {
  return fields.every(
    (field) =>
      left[field] !== undefined &&
      right[field] !== undefined &&
      left[field] === right[field],
  );
}

function pathIdentity(value) {
  return process.platform === "win32" ? value.toLowerCase() : value;
}

function lstatOrMissing(fs, file) {
  try {
    return fs.lstatSync(file, { bigint: true });
  } catch (cause) {
    if (cause?.code === "ENOENT") return null;
    if (cause?.code === "ENOTDIR")
      throw failure("CC_SETTINGS_SOURCE_UNSAFE", cause);
    throw cause;
  }
}

function assertRegularFile(stat) {
  if (!stat.isFile() || stat.isSymbolicLink() || stat.nlink !== 1n) {
    throw failure("CC_SETTINGS_SOURCE_UNSAFE");
  }
}

function freezeJson(value) {
  const pending = [value];
  while (pending.length) {
    const current = pending.pop();
    if (!current || typeof current !== "object") continue;
    for (const child of Object.values(current)) pending.push(child);
    Object.freeze(current);
  }
  return value;
}

function inspect(file, fs, maxBytes) {
  const logicalPath = path.resolve(file);
  const entry = lstatOrMissing(fs, logicalPath);
  if (entry) assertRegularFile(entry);

  // Preserve absent candidates too, including a missing .claude directory.
  let logicalParent = path.dirname(logicalPath);
  const remaining = [path.basename(logicalPath)];
  while (!lstatOrMissing(fs, logicalParent)) {
    const next = path.dirname(logicalParent);
    if (next === logicalParent) throw failure("CC_SETTINGS_SOURCE_UNAVAILABLE");
    remaining.unshift(path.basename(logicalParent));
    logicalParent = next;
  }
  const canonicalParent = fs.realpathSync(logicalParent);
  const physicalPath = path.join(canonicalParent, ...remaining);
  const flags =
    (fs.constants?.O_RDONLY ?? fsDefault.constants.O_RDONLY) |
    (fs.constants?.O_NOFOLLOW ?? fsDefault.constants.O_NOFOLLOW ?? 0) |
    (fs.constants?.O_NONBLOCK ?? fsDefault.constants.O_NONBLOCK ?? 0);
  const descriptors = [];
  function open(filePath) {
    const fd = fs.openSync(filePath, flags);
    descriptors.push(fd);
    return fd;
  }
  function verifyParent(original) {
    if (
      pathIdentity(fs.realpathSync(logicalParent)) !==
      pathIdentity(canonicalParent)
    ) {
      throw failure("CC_SETTINGS_SOURCE_CHANGED");
    }
    const current = fs.fstatSync(open(canonicalParent), { bigint: true });
    if (
      !current.isDirectory() ||
      !sameFields(original, current, ["dev", "ino", "mode"])
    ) {
      throw failure("CC_SETTINGS_SOURCE_CHANGED");
    }
  }

  function readOpenedSource() {
    // Comparing opened handles avoids Node 22.12 Windows path-stat's projected
    // zero device; both identities come from the same API and real volume.
    const parent = fs.fstatSync(open(canonicalParent), { bigint: true });
    if (!parent.isDirectory()) throw failure("CC_SETTINGS_SOURCE_UNSAFE");
    const common = {
      logicalPath,
      physicalPath,
      nearestExistingParent: canonicalParent,
      remainingPath: path.join(...remaining),
      parentIdentity: Object.freeze({
        dev: String(parent.dev),
        ino: String(parent.ino),
      }),
    };
    if (!entry) {
      if (lstatOrMissing(fs, logicalPath))
        throw failure("CC_SETTINGS_SOURCE_CHANGED");
      verifyParent(parent);
      if (lstatOrMissing(fs, path.join(logicalParent, remaining[0])))
        throw failure("CC_SETTINGS_SOURCE_CHANGED");
      if (lstatOrMissing(fs, physicalPath))
        throw failure("CC_SETTINGS_SOURCE_CHANGED");
      return Object.freeze({
        ...common,
        exists: false,
        byteLength: 0,
        digest: null,
        fileIdentity: null,
        settings: null,
      });
    }

    const fd = open(physicalPath);
    const before = fs.fstatSync(fd, { bigint: true });
    assertRegularFile(before);
    if (before.size > BigInt(maxBytes))
      throw failure("CC_SETTINGS_SOURCE_TOO_LARGE");
    const buffer = Buffer.alloc(maxBytes + 1);
    let length = 0;
    for (;;) {
      const count = fs.readSync(
        fd,
        buffer,
        length,
        buffer.length - length,
        length,
      );
      if (!count) break;
      length += count;
      if (length > maxBytes) throw failure("CC_SETTINGS_SOURCE_TOO_LARGE");
    }
    const after = fs.fstatSync(fd, { bigint: true });
    if (
      !sameFields(before, after, FILE_FIELDS) ||
      BigInt(length) !== after.size
    ) {
      throw failure("CC_SETTINGS_SOURCE_CHANGED");
    }
    const finalEntry = lstatOrMissing(fs, logicalPath);
    if (!finalEntry) throw failure("CC_SETTINGS_SOURCE_CHANGED");
    assertRegularFile(finalEntry);
    const reopened = fs.fstatSync(open(physicalPath), { bigint: true });
    if (!sameFields(before, reopened, FILE_FIELDS))
      throw failure("CC_SETTINGS_SOURCE_CHANGED");
    verifyParent(parent);
    const bytes = buffer.subarray(0, length);
    let settings;
    try {
      const text = new TextDecoder("utf-8", {
        fatal: true,
        ignoreBOM: true,
      }).decode(bytes);
      settings = JSON.parse(text);
      if (!settings || typeof settings !== "object" || Array.isArray(settings))
        throw new TypeError("Settings must be an object");
    } catch (cause) {
      throw failure("CC_SETTINGS_SOURCE_INVALID", cause);
    }
    return Object.freeze({
      ...common,
      exists: true,
      byteLength: length,
      digest: createHash("sha256").update(bytes).digest("hex"),
      // Preserve identity from the final fstat on the descriptor whose bytes
      // were parsed and hashed, never a separate path-based stat projection.
      fileIdentity: Object.freeze(
        Object.fromEntries(
          FILE_FIELDS.map((field) => [field, String(after[field])]),
        ),
      ),
      settings: freezeJson(settings),
    });
  }
  let result;
  let bodyError = null;
  let bodyThrew = false;
  let closeError = null;
  try {
    result = readOpenedSource();
  } catch (cause) {
    bodyThrew = true;
    bodyError = cause;
  } finally {
    for (const fd of descriptors.reverse()) {
      try {
        fs.closeSync(fd);
      } catch (cause) {
        closeError ??= cause;
      }
    }
  }
  if (bodyThrew) throw bodyError;
  if (closeError) throw closeError;
  return result;
}

function observeSettingsSource(
  file,
  { fs = fsDefault, maxBytes = MAX_SETTINGS_SOURCE_BYTES } = {},
) {
  if (typeof file !== "string" || !file || file.includes("\0"))
    throw new TypeError("A settings source path is required");
  if (
    !Number.isSafeInteger(maxBytes) ||
    maxBytes < 1 ||
    maxBytes > MAX_SETTINGS_SOURCE_BYTES
  )
    throw new TypeError("Settings source byte limit is invalid");
  try {
    return inspect(file, fs, maxBytes);
  } catch (cause) {
    if (cause?.name === "SettingsSourceObservationError") throw cause;
    throw failure("CC_SETTINGS_SOURCE_UNAVAILABLE", cause);
  }
}

function observeSettingsSources(files, options = {}) {
  if (!Array.isArray(files) || files.length > MAX_SETTINGS_SOURCES)
    throw new TypeError("Settings source list must be bounded");
  // Resolve every input before the first filesystem operation; later chdir
  // cannot change where a remaining relative candidate is inspected.
  const resolved = files.map((file) => {
    if (typeof file !== "string" || !file || file.includes("\0"))
      throw new TypeError("A settings source path is required");
    return path.resolve(file);
  });
  return Object.freeze(
    resolved.map((file) => observeSettingsSource(file, options)),
  );
}

module.exports = {
  MAX_SETTINGS_SOURCE_BYTES,
  MAX_SETTINGS_SOURCES,
  observeSettingsSource,
  observeSettingsSources,
};

import { afterEach, beforeEach, describe, expect, it } from "vitest";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { createHash } from "node:crypto";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import observation from "../../src/lib/settings-source-observation.cjs";
import loader from "../../src/lib/settings-loader.cjs";

const { observeSettingsSource, observeSettingsSources, MAX_SETTINGS_SOURCES } =
  observation;
let root;
let originalHome;

beforeEach(() => {
  root = fs.mkdtempSync(path.join(os.tmpdir(), "cc-settings-observe-"));
  originalHome = loader._deps.homedir;
  loader._deps.homedir = () => path.join(root, "home");
});
afterEach(() => {
  loader._deps.homedir = originalHome;
  fs.rmSync(root, { recursive: true, force: true });
});

function write(relative, value) {
  const file = path.join(root, relative);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(
    file,
    typeof value === "object" && !Buffer.isBuffer(value)
      ? JSON.stringify(value)
      : value,
  );
  return file;
}

function onFirstRead(callback) {
  let called = false;
  return {
    ...fs,
    readSync(...args) {
      const count = fs.readSync(...args);
      if (count && !called) {
        called = true;
        callback();
      }
      return count;
    },
  };
}

describe("strict settings source observations", () => {
  it("derives immutable settings and digest from one descriptor's exact bytes", () => {
    const bytes = '{\n "permissions": {"deny":["Bash"]}, "model":"haiku"\n}\n';
    const file = write(".claude/settings.json", bytes);
    let nonemptyReads = 0;
    let finalReadIdentity;
    let readDescriptor;
    const runtimeFs = {
      ...fs,
      readFileSync() {
        throw new Error("must not reread by path");
      },
      readSync(...args) {
        readDescriptor = args[0];
        const count = fs.readSync(...args);
        if (count) nonemptyReads++;
        return count;
      },
      fstatSync(...args) {
        const stat = fs.fstatSync(...args);
        if (args[0] === readDescriptor) finalReadIdentity = stat;
        return stat;
      },
    };
    const result = observeSettingsSource(file, { fs: runtimeFs });
    expect(result).toMatchObject({
      logicalPath: file,
      physicalPath: fs.realpathSync(file),
      exists: true,
      byteLength: Buffer.byteLength(bytes),
      digest: createHash("sha256").update(bytes).digest("hex"),
      settings: { permissions: { deny: ["Bash"] }, model: "haiku" },
    });
    expect(nonemptyReads).toBe(1);
    expect(result.fileIdentity).toEqual(
      Object.fromEntries(
        ["dev", "ino", "mode", "nlink", "size", "mtimeNs", "ctimeNs"].map(
          (field) => [field, String(finalReadIdentity[field])],
        ),
      ),
    );
    expect(Object.isFrozen(result.fileIdentity)).toBe(true);
    expect(Object.isFrozen(result)).toBe(true);
    expect(Object.isFrozen(result.settings.permissions.deny)).toBe(true);
    expect(() => result.settings.permissions.deny.push("Write")).toThrow();
  });

  it("binds missing directories and a future physical target instead of dropping a candidate", () => {
    const file = path.join(root, "missing", ".claude", "settings.json");
    const before = observeSettingsSource(file);
    expect(before).toMatchObject({
      exists: false,
      nearestExistingParent: fs.realpathSync(root),
      remainingPath: path.join("missing", ".claude", "settings.json"),
      physicalPath: path.join(
        fs.realpathSync(root),
        "missing",
        ".claude",
        "settings.json",
      ),
      digest: null,
      fileIdentity: null,
      settings: null,
    });
    write("missing/.claude/settings.json", { env: { TOOL: "yes" } });
    const after = observeSettingsSource(file);
    expect(after.exists).toBe(true);
    expect(after.physicalPath).toBe(before.physicalPath);
    expect(after.nearestExistingParent).not.toBe(before.nearestExistingParent);
  });

  it("accepts atomic replacement between observations without pinning a permanent file inode", () => {
    const file = write("settings.json", { permissions: { allow: ["Read"] } });
    const before = observeSettingsSource(file);
    const replacement = write("new.json", { permissions: { deny: ["Read"] } });
    fs.renameSync(replacement, file);
    const after = observeSettingsSource(file);
    expect(after.physicalPath).toBe(before.physicalPath);
    expect(after.digest).not.toBe(before.digest);
    expect(before.settings.permissions.allow).toEqual(["Read"]);
    expect(after.settings.permissions.deny).toEqual(["Read"]);
  });

  it("rejects creation of a previously missing parent during the absence check", () => {
    const directory = path.join(root, ".claude");
    let created = false;
    const runtimeFs = {
      ...fs,
      fstatSync(...args) {
        const stat = fs.fstatSync(...args);
        if (!created) {
          created = true;
          fs.mkdirSync(directory);
        }
        return stat;
      },
    };
    expect(() =>
      observeSettingsSource(path.join(directory, "settings.json"), {
        fs: runtimeFs,
      }),
    ).toThrow(expect.objectContaining({ code: "CC_SETTINGS_SOURCE_CHANGED" }));
    expect(fs.existsSync(path.join(directory, "settings.json"))).toBe(false);
  });

  it("closes every opened descriptor even if a close fails, preserving the original read error", () => {
    const file = write("settings.json", "{");
    const outstanding = new Set();
    let failed = false;
    const runtimeFs = {
      ...fs,
      openSync(...args) {
        const fd = fs.openSync(...args);
        outstanding.add(fd);
        return fd;
      },
      closeSync(fd) {
        fs.closeSync(fd);
        outstanding.delete(fd);
        if (!failed) {
          failed = true;
          throw Object.assign(new Error("injected close failure"), {
            code: "EIO",
          });
        }
      },
    };
    expect(() => observeSettingsSource(file, { fs: runtimeFs })).toThrow(
      expect.objectContaining({ code: "CC_SETTINGS_SOURCE_INVALID" }),
    );
    expect(failed).toBe(true);
    expect(outstanding.size).toBe(0);
    fs.writeFileSync(file, "{}");
    expect(() => observeSettingsSource(file, { fs: runtimeFs })).not.toThrow();
  });

  it("rejects an in-place edit while the source is being inspected", () => {
    const file = write("settings.json", { permissions: { allow: ["Read"] } });
    const runtimeFs = onFirstRead(() =>
      fs.writeFileSync(
        file,
        JSON.stringify({ permissions: { deny: ["Read", "Write"] } }),
      ),
    );
    expect(() => observeSettingsSource(file, { fs: runtimeFs })).toThrow(
      expect.objectContaining({ code: "CC_SETTINGS_SOURCE_CHANGED" }),
    );
  });

  it("rejects a concurrent replacement or an OS refusal to perform it while the descriptor is open", () => {
    const file = write("settings.json", { permissions: { allow: ["Read"] } });
    const replacement = write("new.json", { permissions: { deny: ["Read"] } });
    let renameError = null;
    const runtimeFs = onFirstRead(() => {
      try {
        fs.renameSync(replacement, file);
      } catch (cause) {
        renameError = cause;
        throw cause;
      }
    });
    let observedError = null;
    try {
      observeSettingsSource(file, { fs: runtimeFs });
    } catch (cause) {
      observedError = cause;
    }
    if (renameError) {
      // Windows MoveFileEx can refuse to replace an opened target. That is a
      // failed mutation attempt, rather than a successful replacement probe.
      expect(process.platform).toBe("win32");
      expect(["EPERM", "EACCES"]).toContain(renameError.code);
      expect(observedError).toMatchObject({
        code: "CC_SETTINGS_SOURCE_UNAVAILABLE",
        cause: renameError,
      });
      expect(
        JSON.parse(fs.readFileSync(file, "utf8")).permissions.allow,
      ).toEqual(["Read"]);
    } else {
      expect(observedError).toMatchObject({
        code: "CC_SETTINGS_SOURCE_CHANGED",
      });
      expect(
        JSON.parse(fs.readFileSync(file, "utf8")).permissions.deny,
      ).toEqual(["Read"]);
    }
  });

  it("keeps logical directory aliases while checking the canonical physical parent", () => {
    const file = write("physical/settings.json", { model: "haiku" });
    const alias = path.join(root, "alias");
    fs.symlinkSync(
      path.dirname(file),
      alias,
      process.platform === "win32" ? "junction" : "dir",
    );
    const aliased = path.join(alias, "settings.json");
    const sources = observeSettingsSources([file, aliased]);
    expect(sources[0].logicalPath).not.toBe(sources[1].logicalPath);
    expect(sources[0].physicalPath).toBe(sources[1].physicalPath);
    expect(sources[0].digest).toBe(sources[1].digest);
  });

  it("rejects a directory alias rebound to another target during the read", () => {
    const first = write("first/settings.json", { model: "haiku" });
    const second = write("second/settings.json", { model: "sonnet" });
    const alias = path.join(root, "alias");
    const linkType = process.platform === "win32" ? "junction" : "dir";
    fs.symlinkSync(path.dirname(first), alias, linkType);
    const runtimeFs = onFirstRead(() => {
      if (process.platform === "win32") fs.rmdirSync(alias);
      else fs.unlinkSync(alias);
      fs.symlinkSync(path.dirname(second), alias, linkType);
    });
    expect(() =>
      observeSettingsSource(path.join(alias, "settings.json"), {
        fs: runtimeFs,
      }),
    ).toThrow(expect.objectContaining({ code: "CC_SETTINGS_SOURCE_CHANGED" }));
  });

  it("rejects hard links and directories as settings sources", () => {
    const file = write("settings.json", {});
    fs.linkSync(file, path.join(root, "alias.json"));
    expect(() => observeSettingsSource(file)).toThrow(
      expect.objectContaining({ code: "CC_SETTINGS_SOURCE_UNSAFE" }),
    );
    expect(() => observeSettingsSource(root)).toThrow(
      expect.objectContaining({ code: "CC_SETTINGS_SOURCE_UNSAFE" }),
    );
  });

  it.skipIf(process.platform === "win32")(
    "rejects a real final file symlink",
    () => {
      const file = write("settings.json", {});
      const alias = path.join(root, "alias.json");
      fs.symlinkSync(file, alias);
      expect(() => observeSettingsSource(alias)).toThrow(
        expect.objectContaining({ code: "CC_SETTINGS_SOURCE_UNSAFE" }),
      );
    },
  );

  it("rejects a dangling parent link rather than accepting its source as missing", () => {
    const alias = path.join(root, "alias");
    fs.symlinkSync(
      path.join(root, "gone"),
      alias,
      process.platform === "win32" ? "junction" : "dir",
    );
    expect(() =>
      observeSettingsSource(path.join(alias, "settings.json")),
    ).toThrow(
      expect.objectContaining({ code: "CC_SETTINGS_SOURCE_UNAVAILABLE" }),
    );
  });

  it("only treats ENOENT as absence and preserves other filesystem failure classifications", () => {
    const cause = Object.assign(new Error("private path omitted"), {
      code: "EACCES",
    });
    const runtimeFs = {
      ...fs,
      lstatSync() {
        throw cause;
      },
    };
    expect(() =>
      observeSettingsSource(path.join(root, "settings.json"), {
        fs: runtimeFs,
      }),
    ).toThrow(
      expect.objectContaining({
        code: "CC_SETTINGS_SOURCE_UNAVAILABLE",
        cause,
      }),
    );
    const file = write("parent", "regular file");
    expect(() =>
      observeSettingsSource(path.join(file, "settings.json")),
    ).toThrow(expect.objectContaining({ code: "CC_SETTINGS_SOURCE_UNSAFE" }));
  });

  it("bounds both a declared large file and growth after opening", () => {
    const file = write("settings.json", '{"x":"123456789"}');
    expect(() => observeSettingsSource(file, { maxBytes: 8 })).toThrow(
      expect.objectContaining({ code: "CC_SETTINGS_SOURCE_TOO_LARGE" }),
    );
    fs.writeFileSync(file, "{}");
    const runtimeFs = onFirstRead(() =>
      fs.appendFileSync(file, " ".repeat(40)),
    );
    expect(() =>
      observeSettingsSource(file, { fs: runtimeFs, maxBytes: 16 }),
    ).toThrow(
